```{.r .cell-code}
# Tabla de frecuencia para variable (ej: Genero)
tabla <- datos %>%
  count(Genero, name = "fi") %>%
  mutate(
    hi = fi / sum(fi),
    Fi = cumsum(fi),
    Hi = cumsum(hi)
  )
# Mostrar tabla bonita
tabla %>%
  gt() %>%
  cols_label(
    Genero = "Categoría",
    fi = "fᵢ",
    hi = "hᵢ",
    Fi = "Fᵢ",
    Hi = "Hᵢ"
  )
```

